{"styles":{"color":{"background":"#FCF8F2","text":"#2E170E"},"typography":{"fontFamily":"Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif","fontSize":"16px","lineHeight":"1.7"},"elements":{"heading":{"color":{"text":"#2E170E"},"typography":{"fontFamily":"Inter, ui-sans-serif, system-ui, sans-serif","fontWeight":"750","lineHeight":"1.2"}},"link":{"color":{"text":"#B83B32"},"typography":{"textDecoration":"none"}},"button":{"color":{"text":"#FFFFFF","background":"#B83B32"},"border":{"radius":"999px"},"typography":{"fontWeight":"700"},"spacing":{"padding":{"top":"12px","right":"20px","bottom":"12px","left":"20px"}}}},"blocks":{"core/group":{"spacing":{"blockGap":"24px"}},"core/columns":{"spacing":{"blockGap":"22px"}}},"css":"
/* AI Tools Guiders — site-wide visual system */
:root{
 --atg-ink:#172033;
 --atg-muted:#667085;
 --atg-primary:#5b5ce2;
 --atg-primary-dark:#4445bd;
 --atg-cyan:#16b8c5;
 --atg-bg:#f6f8fc;
 --atg-surface:#ffffff;
 --atg-border:#e5e9f2;
 --atg-shadow:0 12px 32px rgba(25,35,65,.07);
}
html{scroll-behavior:smooth}
body{background:var(--atg-bg);color:var(--atg-ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;line-height:1.7}
a{color:var(--atg-primary);text-underline-offset:3px}
a:hover{color:var(--atg-primary-dark)}
h1,h2,h3,h4,h5,h6{color:var(--atg-ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;line-height:1.2;letter-spacing:-.025em}
h1{font-size:clamp(2rem,4vw,3.25rem);font-weight:800}
h2{font-size:clamp(1.45rem,2.5vw,2rem);font-weight:750}
h3{font-size:1.2rem;font-weight:700}
p,li{color:#475467}
.site-header{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.94)!important;border-bottom:1px solid var(--atg-border)!important;box-shadow:0 3px 16px rgba(20,30,60,.04);backdrop-filter:blur(14px)}
.site-header .wrap{max-width:1200px;margin-inline:auto;padding:12px 24px}
.site-header .brand{font-size:1.12rem;font-weight:850;letter-spacing:-.04em;color:var(--atg-ink);text-decoration:none}
.site-header .brand mark{color:var(--atg-primary)!important}
.site-header .nav-links a{font-size:13px;font-weight:650;text-decoration:none;color:#344054;padding:9px 11px;border-radius:9px}
.site-header .nav-links a:hover{background:#f0f1ff;color:var(--atg-primary)}
.wp-site-blocks main,.wp-block-post-content{max-width:1160px;margin-inline:auto}
.wp-block-post-content{padding:36px 24px 64px}
.wp-block-post-content> .wp-block-group,
.wp-block-post-content> .wp-block-columns,
.wp-block-post-content> .wp-block-cover{margin-block:24px}
.wp-block-group.is-layout-constrained,.wp-block-columns{gap:22px}
.wp-block-post-content .wp-block-group.has-background,
.wp-block-post-content .wp-block-column,
.wp-block-post-content .wp-block-cover,
.wp-block-post-content .wp-block-media-text{border-radius:16px}
.wp-block-post-content .wp-block-image img,
.wp-block-post-content figure img{border-radius:14px;box-shadow:var(--atg-shadow);height:auto}
.wp-block-post-content .wp-block-button__link,
.wp-element-button{background:var(--atg-primary);color:#fff!important;border-radius:10px;padding:12px 20px;font-weight:700;text-decoration:none;box-shadow:0 5px 14px rgba(91,92,226,.18);transition:transform .18s ease,background .18s ease}
.wp-block-post-content .wp-block-button__link:hover,.wp-element-button:hover{background:var(--atg-primary-dark);transform:translateY(-1px)}
.wp-block-post-content .wp-block-table{border:1px solid var(--atg-border);border-radius:12px;overflow:hidden;background:#fff}
.wp-block-post-content .wp-block-table table{border-collapse:collapse}
.wp-block-post-content .wp-block-table th{background:#f0f2ff;color:#27315b;font-weight:750}
.wp-block-post-content .wp-block-table td,.wp-block-post-content .wp-block-table th{padding:13px 15px;border-color:var(--atg-border)}
.wp-block-post-content .wp-block-separator{border-color:var(--atg-border);opacity:1}
.wp-block-post-content .wp-block-quote{border-left:4px solid var(--atg-primary);background:#f0f2ff;padding:18px 22px;border-radius:0 12px 12px 0}
.wp-block-post-content .wp-block-details{background:#fff;border:1px solid var(--atg-border);border-radius:12px;padding:14px 18px;margin-block:10px}
.wp-block-post-content .wp-block-details summary{font-weight:700;color:var(--atg-ink);cursor:pointer}
.wp-block-post-content .wp-block-list li{margin-block:7px}
.footer{background:#151d32!important;color:#e9edfa!important;margin-top:48px}
.footer .wrap{max-width:1160px;margin-inline:auto;padding-inline:24px}
.footer h3{color:#fff;font-size:1rem}
.footer p,.footer a{color:#c5cce0!important}
.footer a{text-decoration:none}
.footer a:hover{color:#fff!important;text-decoration:underline}
.footer .brand{color:#fff;font-size:1.2rem}
.footer .brand mark{color:#9b9cff!important}
.footer-bottom{border-top:1px solid rgba(255,255,255,.14);padding-top:18px;margin-top:28px}
@media(max-width:782px){
 .site-header .wrap{padding:10px 16px;flex-wrap:wrap}
 .site-header .nav-links{overflow-x:auto;max-width:100%;white-space:nowrap}
 .wp-block-post-content{padding:24px 16px 44px}
 .wp-block-columns{flex-wrap:wrap!important}
 .wp-block-columns>.wp-block-column{flex-basis:100%!important}
 .footer .footer-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:480px){.footer .footer-grid{grid-template-columns:1fr}}

/* Reusable page components for product guides, category pages and comparisons */
.wp-block-post-content .wp-block-group.has-background{
 border:1px solid var(--atg-border);
 border-radius:16px;
 box-shadow:var(--atg-shadow);
}
.wp-block-post-content .wp-block-columns>.wp-block-column{
 background:#fff;
 border:1px solid var(--atg-border);
 border-radius:16px;
 padding:22px;
 box-shadow:var(--atg-shadow);
}
.wp-block-post-content .wp-block-image figcaption,
.wp-block-post-content figcaption{color:var(--atg-muted);font-size:.875rem;line-height:1.5;margin-top:9px}
.wp-block-post-content .wp-block-buttons{gap:12px}
.wp-block-post-content .wp-block-button.is-style-outline .wp-block-button__link{background:transparent;color:var(--atg-primary)!important;border:1px solid var(--atg-primary)}
.wp-block-post-content .wp-block-button.is-style-outline .wp-block-button__link:hover{background:#f0f1ff}
.wp-block-post-content .wp-block-table tbody tr:nth-child(even){background:#fafbff}
.wp-block-post-content .wp-block-table td:first-child{font-weight:650;color:#27315b}
.wp-block-post-content .wp-block-embed{border-radius:16px;overflow:hidden}
.wp-block-post-content .wp-block-video video{border-radius:14px}
.wp-block-post-content .wp-block-post-title{max-width:850px}
.wp-block-post-content .wp-block-heading{scroll-margin-top:100px}
.wp-block-post-content .wp-block-group.alignwide,
.wp-block-post-content .wp-block-columns.alignwide{max-width:1160px}
.wp-block-post-content .wp-block-group.alignfull,
.wp-block-post-content .wp-block-cover.alignfull{margin-left:calc(50% - 50vw);margin-right:calc(50% - 50vw);padding-left:max(24px,calc((100vw - 1160px)/2));padding-right:max(24px,calc((100vw - 1160px)/2))}
@media(max-width:782px){
 .wp-block-post-content .wp-block-columns>.wp-block-column{padding:18px}
 .wp-block-post-content .wp-block-group.alignfull,
 .wp-block-post-content .wp-block-cover.alignfull{padding-left:16px;padding-right:16px}
}

/* AI Tools Guiders — polished submission page, header and footer */
.site-header,
header.site-header,
.wp-site-blocks header.site-header{
 background:#ffffff!important;
 background-color:#ffffff!important;
 border-bottom:1px solid #e7e9f4!important;
 box-shadow:0 5px 22px rgba(28,35,75,.07)!important;
}
.site-header .wrap{
 max-width:1200px!important;
 min-height:76px;
 display:flex;
 align-items:center;
 justify-content:space-between;
 gap:24px;
 padding:12px 24px!important;
}
.site-header .brand,
.site-header a.brand{
 color:#172033!important;
 font-size:1.25rem!important;
 font-weight:850!important;
 letter-spacing:-.045em;
}
.site-header .brand mark{color:#5b5ce2!important}
.site-header .nav-links a,
.site-header .wp-block-navigation-item__content{
 color:#344054!important;
 font-weight:650!important;
 border-radius:9px;
 padding:9px 12px;
 text-decoration:none!important;
}
.site-header .nav-links a:hover,
.site-header .wp-block-navigation-item__content:hover{
 color:#4b4dc7!important;
 background:#f0f1ff!important;
}
.site-header .wp-block-navigation__responsive-container-open,
.site-header .wp-block-navigation__responsive-container-close{color:#172033!important}

footer.footer,.wp-site-blocks footer.footer{
 background:#151d32!important;
 background-color:#151d32!important;
 color:#e8ecf8!important;
 border-top:4px solid #5b5ce2;
 margin-top:56px!important;
 padding:52px 0 26px!important;
}
.footer .wrap{max-width:1160px!important;padding:0 24px!important}
.footer .footer-grid{
 display:grid!important;
 grid-template-columns:1.5fr 1fr 1fr 1fr;
 gap:38px!important;
 align-items:start;
}
.footer h2,.footer h3,.footer h4{color:#fff!important;font-weight:750}
.footer p,.footer li{color:#c5cce0!important}
.footer a,.footer .wp-block-navigation-item__content{
 color:#cbd2ea!important;
 text-decoration:none!important;
 transition:color .18s ease;
}
.footer a:hover{color:#fff!important;text-decoration:underline!important}
.footer .brand,.footer p.brand{color:#fff!important;font-size:1.25rem;font-weight:850}
.footer .brand mark{color:#a6a8ff!important}
.footer-bottom{
 border-top:1px solid rgba(225,231,255,.16);
 margin-top:34px!important;
 padding-top:18px!important;
 color:#aeb8d1!important;
 display:flex;
 justify-content:space-between;
 gap:16px;
 flex-wrap:wrap;
}
.footer-bottom p{color:#aeb8d1!important;font-size:.82rem}
.footer-submit-link{
 margin-top:28px!important;
 padding:16px 18px;
 border:1px solid rgba(188,195,255,.22);
 background:rgba(255,255,255,.045);
 border-radius:12px;
}
.footer-submit-link a{color:#fff!important;font-weight:700}

/* Submission page layout */
.atg-submit-page{
 max-width:100%!important;
 padding:28px 20px 64px;
 color:#172033;
}
.atg-submit-page>.page-hero{
 max-width:1120px;
 margin:12px auto 32px!important;
 padding:48px clamp(24px,5vw,64px)!important;
 border:1px solid #e3e6fb;
 border-radius:22px!important;
 background:linear-gradient(125deg,#f0f1ff 0%,#f5fbff 58%,#e9fbfa 100%)!important;
 box-shadow:0 14px 38px rgba(41,52,111,.08);
}
.atg-submit-page .eyebrow{
 color:#5558cf!important;
 font-size:.78rem;
 font-weight:800;
 letter-spacing:.13em;
 text-transform:uppercase;
 margin-bottom:12px;
}
.atg-submit-page .page-hero h1{
 color:#172033!important;
 font-size:clamp(2rem,4vw,3.1rem);
 line-height:1.12;
 letter-spacing:-.045em;
 margin:0 0 16px;
}
.atg-submit-page .page-hero p{
 max-width:760px;
 color:#596579!important;
 font-size:1.05rem;
}
.atg-submit-page>.section{
 max-width:920px;
 margin:0 auto!important;
 padding:clamp(22px,4vw,44px)!important;
 background:#fff!important;
 border:1px solid #e6e9f2!important;
 border-radius:20px!important;
 box-shadow:0 14px 40px rgba(23,32,51,.07)!important;
}
.atg-submit-page .section>h2{
 color:#172033;
 font-size:1.8rem;
 margin-bottom:8px;
}
.atg-submit-page .section>p{color:#667085}
.atg-submit-page .wp-block-jetpack-contact-form,
.atg-submit-page .contact-form{
 margin-top:26px;
}
.atg-submit-page .grunion-field-wrap,
.atg-submit-page .wp-block-jetpack-field-name,
.atg-submit-page .wp-block-jetpack-field-email,
.atg-submit-page .wp-block-jetpack-field-text,
.atg-submit-page .wp-block-jetpack-field-website,
.atg-submit-page .wp-block-jetpack-field-textarea,
.atg-submit-page .wp-block-jetpack-field-select,
.atg-submit-page .wp-block-jetpack-field-checkbox{
 margin:0 0 20px!important;
}
.atg-submit-page label,
.atg-submit-page .grunion-field-label{
 display:block;
 color:#27324a!important;
 font-size:.94rem!important;
 font-weight:700!important;
 margin:0 0 8px!important;
}
.atg-submit-page input[type="text"],
.atg-submit-page input[type="email"],
.atg-submit-page input[type="url"],
.atg-submit-page input[type="number"],
.atg-submit-page select,
.atg-submit-page textarea,
.atg-submit-page .contact-form input[type="text"],
.atg-submit-page .contact-form input[type="email"],
.atg-submit-page .contact-form input[type="url"],
.atg-submit-page .contact-form textarea{
 display:block;
 width:100%!important;
 min-height:48px;
 padding:12px 14px!important;
 color:#172033!important;
 background:#fbfcff!important;
 border:1px solid #dce1ed!important;
 border-radius:10px!important;
 box-shadow:none!important;
 font:inherit;
 line-height:1.5;
 box-sizing:border-box;
 transition:border-color .18s ease,box-shadow .18s ease,background .18s ease;
}
.atg-submit-page textarea,
.atg-submit-page .contact-form textarea{
 min-height:130px;
 resize:vertical;
}
.atg-submit-page input:focus,
.atg-submit-page select:focus,
.atg-submit-page textarea:focus{
 outline:none!important;
 border-color:#6668e8!important;
 background:#fff!important;
 box-shadow:0 0 0 3px rgba(91,92,226,.13)!important;
}
.atg-submit-page input[type="checkbox"]{
 width:18px;height:18px;accent-color:#5b5ce2;vertical-align:middle;margin-right:8px;
}
.atg-submit-page .wp-block-jetpack-button button,
.atg-submit-page .contact-form input[type="submit"],
.atg-submit-page .contact-form button,
.atg-submit-page button[type="submit"]{
 display:inline-flex!important;
 align-items:center;
 justify-content:center;
 min-height:52px;
 padding:13px 28px!important;
 border:0!important;
 border-radius:11px!important;
 background:linear-gradient(135deg,#6264e8,#484ac5)!important;
 color:#fff!important;
 font-size:1rem!important;
 font-weight:750!important;
 letter-spacing:.01em;
 box-shadow:0 8px 20px rgba(83,85,210,.24)!important;
 cursor:pointer;
 transition:transform .18s ease,box-shadow .18s ease,filter .18s ease;
}
.atg-submit-page .wp-block-jetpack-button button:hover,
.atg-submit-page .contact-form input[type="submit"]:hover,
.atg-submit-page .contact-form button:hover,
.atg-submit-page button[type="submit"]:hover{
 filter:brightness(1.06);
 transform:translateY(-2px);
 box-shadow:0 12px 25px rgba(83,85,210,.3)!important;
}
.atg-submit-page .atg-submission-note{
 margin-top:24px;
 padding:16px 18px;
 border:1px solid #dce9fb;
 border-left:4px solid #16b8c5;
 border-radius:10px;
 background:#f4faff;
 color:#536176;
 font-size:.92rem;
}
@media(max-width:782px){
 .site-header .wrap{min-height:unset;padding:12px 16px!important;flex-wrap:wrap}
 .footer .footer-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:26px!important}
 .atg-submit-page{padding:18px 12px 44px}
 .atg-submit-page>.page-hero{padding:30px 22px!important;border-radius:16px!important}
 .atg-submit-page>.section{padding:22px 18px!important;border-radius:16px!important}
}
@media(max-width:480px){
 .footer .footer-grid{grid-template-columns:1fr}
 .atg-submit-page .contact-form input[type="submit"]{width:100%}
}

/* AI Tools Guiders — Panera-inspired warm editorial system (site-wide) */
:root{
 --atg-ink:#2e170e!important;
 --atg-muted:#755f52!important;
 --atg-primary:#b83b32!important;
 --atg-primary-dark:#922c25!important;
 --atg-cyan:#d99b2b!important;
 --atg-bg:#fcf8f2!important;
 --atg-surface:#ffffff!important;
 --atg-border:#e8d9c8!important;
 --atg-gold:#eab943;
 --atg-shadow:0 8px 24px rgba(64,35,19,.075);
}
html,body{background:#fcf8f2!important;color:#2e170e!important}
body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif!important;line-height:1.7}
a{color:#a83b30;text-underline-offset:3px}
a:hover{color:#7d281f}
h1,h2,h3,h4,h5,h6,.wp-block-post-title{color:#2e170e!important;letter-spacing:-.025em}
p,li{color:#5f4a3e}
.site-header,header.site-header,.wp-site-blocks header.site-header{
 background:#fffdf9!important;background-color:#fffdf9!important;
 border-bottom:1px solid #e8d9c8!important;
 box-shadow:0 3px 16px rgba(54,30,17,.055)!important;
}
.site-header .brand,.site-header a.brand{color:#2e170e!important}
.site-header .brand mark{color:#b83b32!important}
.site-header .nav-links a,.site-header .wp-block-navigation-item__content{
 color:#4d382d!important;border-radius:8px;text-decoration:none!important
}
.site-header .nav-links a:hover,.site-header .wp-block-navigation-item__content:hover{
 color:#8f3028!important;background:#f8eee2!important
}
.wp-site-blocks main,.wp-block-post-content{color:#2e170e}
.wp-block-post-content{max-width:1160px}
.wp-block-post-content>.wp-block-group,
.wp-block-post-content>.wp-block-columns,
.wp-block-post-content>.wp-block-cover{margin-block:26px}
.wp-block-post-content .wp-block-group.has-background,
.wp-block-post-content .wp-block-column,
.wp-block-post-content .wp-block-media-text,
.wp-block-post-content .wp-block-cover{
 border:1px solid #eadbca!important;border-radius:15px!important;
 box-shadow:var(--atg-shadow)!important
}
.wp-block-post-content .wp-block-columns>.wp-block-column{
 background:#fff!important;padding:20px!important
}
.wp-block-post-content .wp-block-image img,
.wp-block-post-content figure img{border-radius:12px;box-shadow:var(--atg-shadow)}
.wp-block-post-content .wp-block-button__link,.wp-element-button,
.atg-submit-page .wp-block-jetpack-button button,
.atg-submit-page .contact-form input[type="submit"]{
 background:#b83b32!important;color:#fff!important;border:0!important;
 border-radius:999px!important;padding:12px 21px!important;
 font-weight:750!important;box-shadow:0 5px 14px rgba(184,59,50,.18)!important
}
.wp-block-post-content .wp-block-button__link:hover,.wp-element-button:hover{
 background:#922c25!important;transform:translateY(-1px)
}
.wp-block-post-content .wp-block-button.is-style-outline .wp-block-button__link{
 background:transparent!important;color:#9e342b!important;border:1px solid #c96b5e!important
}
.wp-block-post-content .wp-block-table{
 border:1px solid #e8d9c8!important;border-radius:12px!important;
 overflow:hidden;background:#fff!important;box-shadow:0 4px 16px rgba(64,35,19,.045)
}
.wp-block-post-content .wp-block-table table{border-collapse:collapse}
.wp-block-post-content .wp-block-table th{
 background:#f3e5d3!important;color:#432719!important;font-weight:750
}
.wp-block-post-content .wp-block-table td,.wp-block-post-content .wp-block-table th{
 padding:13px 15px;border-color:#eadbca!important
}
.wp-block-post-content .wp-block-table tbody tr:nth-child(even){background:#fcf8f2!important}
.wp-block-post-content .wp-block-table td:first-child{font-weight:650;color:#432719}
.wp-block-post-content .wp-block-details{
 background:#fff!important;border:1px solid #e8d9c8!important;
 border-radius:11px!important;padding:14px 18px;margin-block:10px;
 box-shadow:0 3px 12px rgba(64,35,19,.04)
}
.wp-block-post-content .wp-block-details summary{font-weight:700;color:#2e170e;cursor:pointer}
.wp-block-post-content .wp-block-quote{
 border-left:4px solid #eab943!important;background:#f8efe3!important;
 padding:18px 22px;border-radius:0 12px 12px 0
}
.wp-block-post-content .wp-block-separator{border-color:#e8d9c8!important}
.wp-block-post-content figcaption{color:#806b5d}
.footer,.wp-site-blocks footer.footer,footer.footer{
 background:#2e170e!important;background-color:#2e170e!important;
 color:#f9eee2!important;border-top:4px solid #eab943!important;
}
.footer h2,.footer h3,.footer h4{color:#fff8ef!important}
.footer p,.footer li,.footer a{color:#e4d2c0!important}
.footer a:hover{color:#fff!important}
.footer .brand,.footer p.brand{color:#fff8ef!important}
.footer .brand mark{color:#eab943!important}
.footer-bottom{border-top:1px solid rgba(255,238,220,.18)!important}
.footer-bottom p{color:#d2bba5!important}
.atg-submit-page{color:#2e170e!important}
.atg-submit-page>.page-hero{
 background:linear-gradient(125deg,#f8ead6 0%,#fffaf2 62%,#f4e2c8 100%)!important;
 border:1px solid #ead5b9!important;box-shadow:var(--atg-shadow)!important
}
.atg-submit-page .page-hero h1,.atg-submit-page .section>h2{color:#2e170e!important}
.atg-submit-page .eyebrow{color:#a83b30!important}
.atg-submit-page>.section{border-color:#eadbca!important;box-shadow:var(--atg-shadow)!important}
.atg-submit-page input:focus,.atg-submit-page select:focus,.atg-submit-page textarea:focus{
 border-color:#c78d35!important;box-shadow:0 0 0 3px rgba(234,185,67,.2)!important
}
@media(max-width:782px){
 .wp-block-post-content .wp-block-columns>.wp-block-column{padding:17px!important}
}


/* Final warm-theme consistency pass: neutralize leftover blue controls */
:root{
 --wp--preset--color--primary:#B83B32;
 --wp--preset--color--secondary:#922C25;
 --wp--preset--color--accent-1:#B83B32;
 --wp--preset--color--accent-2:#FCF8F2;
 --wp--preset--color--accent-3:#F3E5D3;
 --wp--preset--color--contrast:#2E170E;
 --wp--preset--color--base:#FCF8F2;
 --wp--preset--color--accent:#EAB943;
 --wp--preset--color--vivid-cyan-blue:#B83B32;
 --wp--preset--color--vivid-purple:#B83B32;
 --wp--preset--color--pale-cyan-blue:#F3E5D3;
 --wp--preset--color--light-blue:#F3E5D3;
 --wp--preset--color--blue:#B83B32;
 --wp--preset--color--deep-blue:#922C25;
 --atg-ink:#2E170E;
 --atg-primary:#B83B32;
 --atg-primary-dark:#922C25;
 --atg-gold:#EAB943;
 --atg-bg:#FCF8F2;
 --atg-border:#E8D9C8;
}
.wp-block-button__link,.wp-element-button,
button,.button,a.button,
input[type="button"],input[type="submit"],input[type="reset"],
.wp-block-search__button,.wp-block-query-pagination a,
.wp-block-post-navigation-link a,.wp-block-file__button,
.wp-block-loginout a,.wp-block-read-more,
.woocommerce a.button,.woocommerce button.button,
.woocommerce input.button,.woocommerce #respond input#submit,
.jetpack-submit-button{
 background-color:#B83B32!important;
 background-image:none!important;
 border-color:#B83B32!important;
 color:#FFFFFF!important;
}
.wp-block-button__link:hover,.wp-element-button:hover,
button:hover,.button:hover,a.button:hover,
input[type="button"]:hover,input[type="submit"]:hover,input[type="reset"]:hover,
.wp-block-search__button:hover,.wp-block-query-pagination a:hover,
.wp-block-file__button:hover,.woocommerce a.button:hover,
.woocommerce button.button:hover,.woocommerce input.button:hover{
 background-color:#922C25!important;
 border-color:#922C25!important;
 color:#FFFFFF!important;
}
.wp-block-button.is-style-outline .wp-block-button__link,
.is-style-outline>.wp-block-button__link{
 background:transparent!important;
 color:#A7352D!important;
 border:1px solid #B83B32!important;
}
.wp-block-button.is-style-outline .wp-block-button__link:hover,
.is-style-outline>.wp-block-button__link:hover{
 background:#F8EEE2!important;color:#922C25!important;
}
.wp-block-post-content [class*="has-primary-background-color"],
.wp-block-post-content [class*="has-accent-1-background-color"],
.wp-block-post-content [style*="background-color: rgb(91, 92, 226)"],
.wp-block-post-content [style*="background-color:#5b5ce2"],
.wp-block-post-content [style*="background-color: #5b5ce2"]{
 background-color:#B83B32!important;
}
.wp-block-post-content [class*="has-primary-color"],
.wp-block-post-content [class*="has-accent-1-color"]{
 color:#A7352D!important;
}
.wp-block-post-content .wp-block-table th,
.wp-block-post-content .wp-block-table thead,
.wp-block-post-content .wp-block-table thead tr{
 background:#F3E5D3!important;color:#432719!important;
}
.wp-block-post-content .wp-block-table tbody tr:nth-child(even){background:#FCF8F2!important}
.wp-block-post-content .wp-block-details,
.wp-block-post-content .wp-block-columns>.wp-block-column,
.wp-block-post-content .wp-block-group.has-background,
.wp-block-post-content .wp-block-media-text,
.wp-block-post-content .wp-block-cover{
 border-color:#E8D9C8!important;
}
.site-header .wp-block-navigation__responsive-container-open,
.site-header .wp-block-navigation__responsive-container-close{color:#2E170E!important}
.site-header .wp-block-navigation-item__content[aria-current],
.site-header .current-menu-item>a,
.site-header .current_page_item>a{color:#A7352D!important}

/* Restrained motion: smooth hover feedback and gentle entrance */
@keyframes atgFadeUp{
 from{opacity:0;transform:translateY(14px)}
 to{opacity:1;transform:translateY(0)}
}
@keyframes atgSoftFade{
 from{opacity:.55}
 to{opacity:1}
}
.wp-block-post-content>.wp-block-group,
.wp-block-post-content>.wp-block-columns,
.wp-block-post-content>.wp-block-cover,
.wp-block-post-content>.wp-block-media-text,
.wp-block-post-content>.wp-block-table,
.wp-block-post-content>.wp-block-details{
 animation:atgFadeUp .55s ease-out both;
}
.wp-block-post-content .wp-block-columns>.wp-block-column,
.wp-block-post-content .wp-block-group.has-background,
.wp-block-post-content .wp-block-details,
.wp-block-post-content .wp-block-table{
 transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease;
}
.wp-block-post-content .wp-block-columns>.wp-block-column:hover,
.wp-block-post-content .wp-block-group.has-background:hover,
.wp-block-post-content .wp-block-details:hover,
.wp-block-post-content .wp-block-table:hover{
 transform:translateY(-3px);
 box-shadow:0 12px 28px rgba(64,35,19,.10)!important;
 border-color:#D8BFA4!important;
}
.wp-block-post-content .wp-block-image img,
.wp-block-post-content figure img{
 transition:transform .3s ease,box-shadow .3s ease;
}
.wp-block-post-content .wp-block-image a:hover img,
.wp-block-post-content figure a:hover img{
 transform:scale(1.015);
}
.wp-block-button__link,.wp-element-button,
button,.button,a.button,
input[type="submit"],.wp-block-search__button{
 transition:background-color .2s ease,color .2s ease,transform .2s ease,box-shadow .2s ease!important;
}
.site-header{transition:box-shadow .2s ease,background-color .2s ease}
a{transition:color .18s ease}
@media(prefers-reduced-motion:reduce){
 *,*::before,*::after{
 animation-duration:.01ms!important;animation-iteration-count:1!important;
 scroll-behavior:auto!important;transition-duration:.01ms!important;
 }
}
@media(max-width:782px){
 .wp-block-post-content>.wp-block-group,
 .wp-block-post-content>.wp-block-columns,
 .wp-block-post-content>.wp-block-cover,
 .wp-block-post-content>.wp-block-media-text{animation-duration:.35s}
 .wp-block-post-content .wp-block-columns>.wp-block-column:hover,
 .wp-block-post-content .wp-block-group.has-background:hover{transform:none}
}

